using System;using SourceContact;using LazySourceContact;
namespace NativeInterval {
public sealed class IntervalSurface {
 readonly V[] source;readonly int[] triangles,bones,order;readonly double[] weights;readonly CompactNode[] nodes;readonly NodeHull[] hulls;readonly BoneHull[] boneHulls;readonly Mat[] binds;Mat[] skin;I[][] cache;bool[] valid;
 public CompactNode[] Nodes=>nodes;
 public IntervalSurface(V[] original,int[] originalTriangles,int[] originalBones,double[] originalWeights,CompactNode[] topology,int[] faceOrder,NodeHull[] allNodeHulls,BoneHull[] allInfluenceHulls,Mat[] originalBinds){source=original;triangles=originalTriangles;bones=originalBones;weights=originalWeights;nodes=topology;order=faceOrder;hulls=allNodeHulls;boneHulls=allInfluenceHulls;binds=originalBinds;if(bones.Length!=source.Length*4||weights.Length!=bones.Length||hulls.Length!=nodes.Length)throw new ArgumentException();foreach(double weight in weights)if(double.IsNaN(weight)||double.IsInfinity(weight)||weight<0)throw new ArgumentException();Validate();}
 void Validate(){if(nodes.Length==0||order.Length*3!=triangles.Length)throw new ArgumentException("Complete original topology required");var seen=new bool[order.Length];var incoming=new int[nodes.Length];for(int index=nodes.Length-1;index>=0;index--){var n=nodes[index];var h=hulls[index];if(h.Count<=0||h.Start<0||h.Start+h.Count>boneHulls.Length||h.SumMin<=0||h.SumMax<h.SumMin)throw new ArgumentException("All-influence range invalid");if(n.Count>0){if(n.Start<0||n.Start+n.Count>order.Length)throw new ArgumentException();for(int f=n.Start;f<n.Start+n.Count;f++){int triangle=order[f];if(triangle<0||triangle>=seen.Length||seen[triangle])throw new ArgumentException("Original face omitted/duplicated");seen[triangle]=true;for(int c=0;c<3;c++){int vertex=triangles[triangle*3+c];if(vertex<0||vertex>=source.Length)throw new ArgumentException();double sum=0;for(int k=0;k<4;k++){int influence=vertex*4+k;double weight=weights[influence];sum+=weight;if(weight==0)continue;bool covered=false;for(int bi=h.Start;bi<h.Start+h.Count;bi++){var box=boneHulls[bi];if(box.Bone==bones[influence]&&box.Bone>=0&&box.Bone<binds.Length){var p=source[vertex];covered=p.X>=box.Min.X&&p.X<=box.Max.X&&p.Y>=box.Min.Y&&p.Y<=box.Max.Y&&p.Z>=box.Min.Z&&p.Z<=box.Max.Z;if(covered)break;}}if(!covered)throw new ArgumentException("Positive original influence escaped metadata");}if(sum<h.SumMin||sum>h.SumMax)throw new ArgumentException("Original weight sum escaped metadata");}}}else{if(n.Left<=index||n.Right<=index||n.Left>=nodes.Length||n.Right>=nodes.Length)throw new ArgumentException("Invalid tree");incoming[n.Left]++;incoming[n.Right]++;foreach(int child in new[]{n.Left,n.Right}){var ch=hulls[child];if(ch.SumMin<h.SumMin||ch.SumMax>h.SumMax)throw new ArgumentException("Child sums escaped parent");for(int ci=ch.Start;ci<ch.Start+ch.Count;ci++){var cb=boneHulls[ci];bool covered=false;for(int pi=h.Start;pi<h.Start+h.Count;pi++){var pb=boneHulls[pi];if(cb.Bone==pb.Bone&&cb.Min.X>=pb.Min.X&&cb.Max.X<=pb.Max.X&&cb.Min.Y>=pb.Min.Y&&cb.Max.Y<=pb.Max.Y&&cb.Min.Z>=pb.Min.Z&&cb.Max.Z<=pb.Max.Z){covered=true;break;}}if(!covered)throw new ArgumentException("Child influence box escaped parent");}}}}foreach(bool face in seen)if(!face)throw new ArgumentException("Missing source face");for(int i=1;i<incoming.Length;i++)if(incoming[i]!=1)throw new ArgumentException("Unreachable/shared node");}
 public bool SetInterval(Mat[] world){skin=null;cache=null;valid=null;if(world==null||world.Length!=binds.Length)return false;try{skin=new Mat[world.Length];for(int i=0;i<world.Length;i++)skin[i]=Mat.Multiply(world[i],binds[i]);cache=new I[nodes.Length][];valid=new bool[nodes.Length];return true;}catch(ArithmeticException){skin=null;return false;}}
 public bool Bound(int node,ref WorkBudget budget,out I[] bounds){bounds=null;if(skin==null)return false;if(valid[node]){bounds=cache[node];return true;}var h=hulls[node];if(h.Count<=0||!budget.Take(h.Count))return false;try{for(int i=h.Start;i<h.Start+h.Count;i++){var bone=boneHulls[i];var b=skin[bone.Bone].Point(new I(bone.Min.X,bone.Max.X),new I(bone.Min.Y,bone.Max.Y),new I(bone.Min.Z,bone.Max.Z));if(bounds==null)bounds=b;else for(int c=0;c<3;c++)bounds[c]=I.Hull(bounds[c],b[c]);}var sum=new I(h.SumMin,h.SumMax);for(int c=0;c<3;c++)bounds[c]=bounds[c]*sum;cache[node]=bounds;valid[node]=true;return true;}catch(ArithmeticException){return false;}}
 // Optional tight leaf bounds: EVERY original triangle corner, all four source weights.
 public bool Leaf(int node,ref WorkBudget budget,out I[] bounds){bounds=null;if(skin==null)return false;var n=nodes[node];try{for(int i=n.Start;i<n.Start+n.Count;i++)for(int corner=0;corner<3;corner++){int vertex=triangles[order[i]*3+corner];if(!budget.Take(4))return false;var p=source[vertex];var v=new[]{I.Point(0),I.Point(0),I.Point(0)};for(int k=0;k<4;k++){int index=vertex*4+k;if(weights[index]==0)continue;var b=skin[bones[index]].Point(I.Point(p.X),I.Point(p.Y),I.Point(p.Z));for(int c=0;c<3;c++)v[c]=v[c]+b[c]*I.Point(weights[index]);}if(bounds==null)bounds=v;else for(int c=0;c<3;c++)bounds[c]=I.Hull(bounds[c],v[c]);}return bounds!=null;}catch(ArithmeticException){return false;}}
}
public enum IntervalVerdict {ProvenSeparated,Indeterminate}
public sealed class IntervalPair {
 readonly int[] sa,sb;public IntervalPair(int stackCapacity){sa=new int[stackCapacity];sb=new int[stackCapacity];}
 static bool Separate(I[] a,I[] b){for(int c=0;c<3;c++)if(a[c].Hi<b[c].Lo||b[c].Hi<a[c].Lo)return true;return false;}
 // A sound negative certificate in the declared exact-math model. Overlap is NOT a hit.
 public IntervalVerdict Inspect(IntervalSurface a,IntervalSurface b,ref WorkBudget budget){if(sa.Length==0)return IntervalVerdict.Indeterminate;int top=1;sa[0]=sb[0]=0;while(top>0){if(!budget.Take(1))return IntervalVerdict.Indeterminate;int x=sa[--top],y=sb[top];I[] al,bl;if(!a.Bound(x,ref budget,out al)||!b.Bound(y,ref budget,out bl))return IntervalVerdict.Indeterminate;if(Separate(al,bl))continue;var p=a.Nodes[x];var q=b.Nodes[y];if(p.Count>0){if(!a.Leaf(x,ref budget,out al))return IntervalVerdict.Indeterminate;if(Separate(al,bl))continue;}if(q.Count>0){if(!b.Leaf(y,ref budget,out bl))return IntervalVerdict.Indeterminate;if(Separate(al,bl))continue;}if(p.Count>0&&q.Count>0)return IntervalVerdict.Indeterminate;if(top+2>sa.Length)return IntervalVerdict.Indeterminate;if(p.Count==0){sa[top]=p.Left;sb[top++]=y;sa[top]=p.Right;sb[top++]=y;}else{sa[top]=x;sb[top++]=q.Left;sa[top]=x;sb[top++]=q.Right;}}
 return IntervalVerdict.ProvenSeparated;}
}
}
